#pragma once

#if CARB_CHECK_ENABLED && !defined(__CUDACC__)
#    include <string>

#    include <carb/Defines.h>
#    include <carb/InterfaceUtils.h>
#    include <omni/fabric/core/interface/IDiagnostics.h>

#    define FABRIC_VALIDATION_COMPILED 1
#    define FABRIC_VALIDATE_IMPL(type, cond, ...)                                                                       \
        (!omni::fabric::isValidationEnabled() || CARB_LIKELY(cond) ||                                                   \
         omni::fabric::handleValidationFailure(type, #cond, CARB_PRETTY_FUNCTION, __FILE__, __LINE__, ##__VA_ARGS__) || \
         (CARB_BREAK_POINT(), false))
#    define FABRIC_VALIDATE(cond, ...)                                                                                 \
        FABRIC_VALIDATE_IMPL(omni::fabric::ValidateType::eContinuable, cond, ##__VA_ARGS__)
#    define FABRIC_VALIDATE_FATAL(cond, ...)                                                                           \
        FABRIC_VALIDATE_IMPL(omni::fabric::ValidateType::eFatal, cond, ##__VA_ARGS__)
#else // #if CARB_CHECK_ENABLED && !defined(__CUDACC__)
#    define FABRIC_VALIDATION_COMPILED 0
#    define FABRIC_VALIDATE(...) (true || false) // "|| false" silences GCC's -Wunused-value
#    define FABRIC_VALIDATE_FATAL(...) (true || false) // "|| false" silences GCC's -Wunused-value
#endif // #if CARB_CHECK_ENABLED && !defined(__CUDACC__)

namespace omni
{
namespace fabric
{

#if FABRIC_VALIDATION_COMPILED
enum class ValidateType : uint8_t
{
    eContinuable, //!< A continuable validate, such as \ref FABRIC_VALIDATE.
    eFatal //!< A fatal validate, such as \ref FABRIC_VALIDATE_FATAL.
};

bool isValidationEnabled();

#    ifndef FABRIC_STATIC
/**
 * Checks if runtime validation is enabled
 * @return true if runtime validation is enabled, false otherwise
 */
inline bool isValidationEnabled()
{
    IDiagnostics* iDiagnostics = carb::getCachedInterface<IDiagnostics>();
    return iDiagnostics && iDiagnostics->isValidationEnabled();
}
#    endif // #ifndef FABRIC_STATIC

/**
 * Handles a validation failure
 * @return true if the execution should continue, false if the execution should be halted
 */
inline bool handleValidationFailure(
    ValidateType type, const char* cond, const char* func, const char* file, int line, const char* fmt = nullptr, ...)
{
    std::string output;
    if (fmt)
    {
        CARB_FORMATTED(fmt, [&](const char* formatted) { output = std::string(formatted); });
    }

    CARB_LOG_ERROR(
        "%s(%d): %s: Validation (%s) failed%c %s", file, line, func, cond, output.empty() ? '.' : ':', output.c_str());

    if (type == ValidateType::eFatal || carb::extras::isDebuggerAttached())
        return false;

    return true;
}
#endif // #if FABRIC_VALIDATION_COMPILED

} // namespace fabric
} // namespace omni
